from dataclasses import dataclass, field


@dataclass
class Point:
    x: int
    tags: list = field(default_factory=list)  # 可变默认值必须走 factory

{
    "source": "基础阶段总纲.txt",   # 出自哪本书 → 引用溯源
    "chunk_id": "基础阶段总纲.txt#003",  # 全局唯一 → 日志/去重
    "chunk_index": 3, "total_chunks": 9,  # 第几块/共几块 → 要不要补相邻块
    "start": 141, "end": 199,          # 原文偏移量 → 高亮定位
}

def score(m, chunk_size):
    if m["oversize"]:
        return -1.0  # 硬约束:一票否决
    fit = max(1 - abs(m["mean"] - chunk_size * 0.8) / (chunk_size * 0.8), 0.0)
    return round(fit, 3)  # 软指标:归一化后加权
